using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
partial class Canvas {
 public int FreehandSpacing=10;
 public static List<PointF> ProportionalPoints(List<PointF> points,int percent){float total=0;for(int i=1;i<points.Count;i++)total+=StrokeSession.Distance(points[i-1],points[i]);return SpacedPoints(points,total*Math.Max(10,Math.Min(50,percent))/100f);}
 public static List<PointF> SpacedPoints(List<PointF> points,float spacing){var result=new List<PointF>{points[0]};float total=0;for(int i=1;i<points.Count;i++)total+=StrokeSession.Distance(points[i-1],points[i]);spacing=Math.Max(spacing,total/7998);float travel=0,next=spacing;for(int i=1;i<points.Count;i++){var a=points[i-1];var b=points[i];float length=StrokeSession.Distance(a,b);while(length>0&&next<=travel+length){float t=(next-travel)/length;result.Add(new PointF(a.X+(b.X-a.X)*t,a.Y+(b.Y-a.Y)*t));next+=spacing;}travel+=length;}if(StrokeSession.Distance(result.Last(),points.Last())>.001f)result.Add(points.Last());return result;}
}
partial class Studio {
 Label pointSpacingLabel;TrackBar pointSpacing=new TrackBar{Minimum=10,Maximum=50,Value=10,TickStyle=TickStyle.None,Width=170,Height=34};
 void AddPointSpacing(FlowLayoutPanel panel){var label=pointSpacingLabel=new Label{Text="Spacing · 10%",Width=180,Height=22,Margin=new Padding(3,12,3,0)};panel.Controls.Add(label);panel.Controls.Add(pointSpacing);label.Enabled=pointSpacing.Enabled=canvas.VectorMode=="Freehand";pointSpacing.ValueChanged+=delegate{canvas.FreehandSpacing=pointSpacing.Value;label.Text="Spacing · "+pointSpacing.Value+"%";};}
 public void TestVersion29(){foreach(int percent in new[]{10,25,50}){var shortLine=Canvas.ProportionalPoints(new List<PointF>{new PointF(0,0),new PointF(100,0)},percent);var longLine=Canvas.ProportionalPoints(new List<PointF>{new PointF(0,0),new PointF(1000,0)},percent);if(shortLine.Count!=longLine.Count||shortLine.Count!=100/percent+1||Math.Abs(shortLine[1].X-percent)>.01||Math.Abs(longLine[1].X-percent*10)>.01)throw new Exception("Proportional spacing at different lengths");}var corner=Canvas.ProportionalPoints(new List<PointF>{new PointF(0,0),new PointF(100,0),new PointF(100,100)},50);if(corner.Count!=3||corner[1]!=new PointF(100,0))throw new Exception("Spacing follows path length");var line=new List<PointF>{new PointF(0,0),new PointF(100,0)};var dense=Canvas.SpacedPoints(line,5);var sparse=Canvas.SpacedPoints(line,25);if(dense.Count!=21||sparse.Count!=5||sparse.Last()!=line.Last())throw new Exception("Regular point spacing");pointSpacing.Value=30;if(canvas.FreehandSpacing!=30)throw new Exception("Spacing slider");
 using(var b=new Bitmap(2,2)){b.SetPixel(0,0,Color.FromArgb(128,100,100,100));b.SetPixel(1,0,Color.Red);var a=new LayerAdjustment();using(var identity=a.Apply(b))if(identity.GetPixel(0,0)!=b.GetPixel(0,0))throw new Exception("Identity adjustment");a.Brightness=20;using(var light=a.Apply(b))if(light.GetPixel(0,0).R<=100||light.GetPixel(0,0).A!=128||light.GetPixel(1,1).A!=0)throw new Exception("Brightness/alpha");a=new LayerAdjustment{Saturation=-100};using(var grey=a.Apply(b))if(grey.GetPixel(1,0).R!=grey.GetPixel(1,0).G)throw new Exception("Saturation");a=new LayerAdjustment{Hue=120};using(var hue=a.Apply(b))if(hue.GetPixel(1,0).G!=255)throw new Exception("Hue");a=new LayerAdjustment{Black=100,White=200};using(var levels=a.Apply(b))if(levels.GetPixel(0,0).R!=0)throw new Exception("Levels");a=new LayerAdjustment{Curve=new[]{0,128,200,230,255}};using(var curve=a.Apply(b))if(curve.GetPixel(0,0).R<=100)throw new Exception("Curves");}
 SetDocument(new Document("A4",100),null);var layer=canvas.Doc.Selected;using(var g=Graphics.FromImage(layer.Image))g.Clear(Color.FromArgb(100,100,100));ApplyAdjustment(layer,new LayerAdjustment{Brightness=20});if(layer.Image.GetPixel(0,0).R!=100||layer.Rendered().GetPixel(0,0).R<=100)throw new Exception("Non-destructive adjustment");Travel(undo,redo);if(!layer.Adjustment.Identity)throw new Exception("Adjustment undo");Travel(redo,undo);if(layer.Adjustment.Brightness!=20)throw new Exception("Adjustment redo");DuplicateLayer();if(canvas.Doc.Selected.Adjustment.Brightness!=20||ReferenceEquals(canvas.Doc.Selected.Adjustment,layer.Adjustment))throw new Exception("Duplicate adjustments");string file=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var d=Document.Load(file)){if(d.Selected.Adjustment.Brightness!=20||d.Selected.Image.GetPixel(0,0).R!=100)throw new Exception("Adjustment project round trip");using(var flat=d.Flatten())if(flat.GetPixel(0,0).R<=100)throw new Exception("Adjusted export");}}finally{if(System.IO.File.Exists(file))System.IO.File.Delete(file);}using(var dialog=new AdjustmentDialog(layer)){if(dialog.Value.Brightness!=20)throw new Exception("Adjustment dialog initial values");}dirty=false;
 }
 public void PreviewAdjustments(){using(var dialog=new AdjustmentDialog(canvas.Doc.Selected)){dialog.ShowInTaskbar=false;dialog.Opacity=0;dialog.Show();using(var b=new Bitmap(dialog.Width,dialog.Height)){dialog.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"adjustments-preview.png"));var tabs=dialog.Controls.OfType<TabControl>().First();for(int i=1;i<tabs.TabPages.Count;i++){tabs.SelectedIndex=i;dialog.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"adjustments-"+i+"-preview.png"));}}}}
}
}
